  {e:"🐾", h:"Describing animals", es:"Describir animales", i:[["It's big / small / fast / slow.","Es grande / pequeño / rápido / lento."],["It can swim / fly / run.","Puede nadar / volar / correr."]], ex:["Birds can fly.","Los pájaros pueden volar."]},
  {e:"🇬🇧", h:"Animals in Britain", es:"Animales en Gran Bretaña", i:[["fox, squirrel, hedgehog","zorro, ardilla, erizo"],["Many British people love dogs.","A muchos británicos les encantan los perros."]], ex:["There's a fox in the garden.","Hay un zorro en el jardín."]}
